      782:     ctxt = xmlCreatePushParserCtxt(NULL, NULL, NULL, 0, NULL);
      783:     xmlSwitchEncoding(ctxt, XML_CHAR_ENCODING_UTF16LE);
      784:     xmlParseChunk(ctxt, utf16, utf16Size, 0);
      785:     xmlParseChunk(ctxt, NULL, 0, 1);
